import '@servicenow/sdk/global'
import { BooleanColumn, IntegerColumn, StringColumn } from '@servicenow/sdk/core'
import { Flow, FlowObject, trigger, wfa } from '@servicenow/sdk/automation'

/**
 * Test flow for setFlowVariables with FlowObject
 * Tests that plain object literals can be assigned to FlowObject flow variables
 */
export const setFlowVariablesFlowObjectTest = Flow(
    {
        $id: Now.ID['set-flow-variables-flow-object-test'],
        name: 'SetFlowVariables FlowObject Test',
        description: 'Test setFlowVariables with FlowObject values',
        flowPriority: 'MEDIUM',
        runAs: 'system',
        runWithRoles: [],
        flowVariables: {
            // Simple FlowObject with primitive fields
            userInfo: FlowObject({
                fields: {
                    name: StringColumn({ label: 'Name', mandatory: false }),
                    age: IntegerColumn({ label: 'Age', mandatory: false }),
                    isActive: BooleanColumn({ label: 'Is Active', mandatory: false }),
                },
                label: 'User Info',
                mandatory: false,
            }),

            // FlowObject with mixed field types
            settings: FlowObject({
                fields: {
                    theme: StringColumn({ label: 'Theme', mandatory: false }),
                    fontSize: IntegerColumn({ label: 'Font Size', mandatory: false }),
                    enabled: BooleanColumn({ label: 'Enabled', mandatory: false }),
                },
                label: 'Settings',
                mandatory: false,
            }),

            // Nested FlowObject
            config: FlowObject({
                fields: {
                    database: FlowObject({
                        fields: {
                            host: StringColumn({ label: 'Host', mandatory: false }),
                            port: IntegerColumn({ label: 'Port', mandatory: false }),
                        },
                        label: 'Database',
                        mandatory: false,
                    }),
                },
                label: 'Config',
                mandatory: false,
            }),
        },
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['set-flow-vars-flow-object-trigger'] },
        {
            table: 'incident',
            condition: '',
            run_on_extended: 'false',
            run_flow_in: 'background',
            run_when_user_list: [],
            run_when_setting: 'both',
            run_when_user_setting: 'any',
        }
    ),
    (params) => {
        // Test 1: Simple FlowObject with plain object literal
        wfa.flowLogic.setFlowVariables(
            {
                $id: Now.ID['set-flow-vars-simple-object'],
                annotation: 'Simple FlowObject with literals',
            },
            params.flowVariables,
            {
                userInfo: {
                    name: 'John Doe',
                    age: 30,
                    isActive: true,
                },
            }
        )

        // Test 2: FlowObject with datapills
        wfa.flowLogic.setFlowVariables(
            {
                $id: Now.ID['set-flow-vars-object-datapills'],
                annotation: 'FlowObject with datapills',
            },
            params.flowVariables,
            {
                userInfo: {
                    name: wfa.dataPill(params.trigger.current.assigned_to.name, 'string'),
                    age: 25,
                    isActive: wfa.dataPill(params.trigger.current.active, 'boolean'),
                },
            }
        )

        // Test 3: FlowObject with mixed literals and datapills
        wfa.flowLogic.setFlowVariables(
            {
                $id: Now.ID['set-flow-vars-mixed-values'],
                annotation: 'Mixed literals and datapills',
            },
            params.flowVariables,
            {
                settings: {
                    theme: 'dark',
                    fontSize: wfa.dataPill(params.trigger.current.priority, 'integer'),
                    enabled: true,
                },
            }
        )

        // Test 4: Nested FlowObject
        wfa.flowLogic.setFlowVariables(
            {
                $id: Now.ID['set-flow-vars-nested-object'],
                annotation: 'Nested FlowObject',
            },
            params.flowVariables,
            {
                config: {
                    database: {
                        host: 'localhost',
                        port: 5432,
                    },
                },
            }
        )
    }
)
